import cyclopts

app = cyclopts.App(name="myapp")


@app.command
def start():
    """Start the service."""
    print("Starting...")


@app.command
def stop():
    """Stop the service."""
    print("Stopping...")


@app.default
def status():
    """Show current status (runs when no subcommand is given)."""
    print("Status: idle")


if __name__ == "__main__":
    app()
